import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import 'package:zan/Features/client/App/ProductsDetails/data/entities/add_to_cart.dart';import '../../../../../../Core/Storage/Remote/api_error_handler.dart';import '../../data/Sources/product_details_sources.dart';import '../../data/entities/product_details.dart';import '../../data/repositories/product_details_repo.dart';class ProductDetailsRepoImpl extends ProductDetailsRepo {  @override  Future<Either<Failure, ProductDetailsEntities>> getProductDetails(      {required int id}) async {    try {      final response = await ProductDetailsSources.getProductDetails(        id: id,      );      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }  @override  Future<Either<Failure, bool>> addToCart({required AddToCart item}) async {    try {      final response = await ProductDetailsSources.addToCart(item: item);      return right(response);    } catch (e) {      // if (e is DioException) {      //   print("object::${e.response?.statusCode}");      //   if (e.response?.statusCode == 401) {      //     return left(ServerFailure.unauthorized());      //   }      //   return left(ServerFailure.fromDioError(e));      // } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      // }    }  }}